const cases = [
  {
    id: "F01",
    message: "A fee appeared on my statement after I cancelled.",
    expected: "billing"
  },
  {
    id: "F02",
    message: "The invoice total is higher than the checkout price.",
    expected: "billing"
  },
  {
    id: "F03",
    message: "Why was my card charged for a free trial?",
    expected: "billing"
  },
  {
    id: "F04",
    message: "The checkout page freezes before I can confirm my purchase.",
    expected: "technical"
  },
  {
    id: "F05",
    message: "The verification code keeps expiring when I reset my password.",
    expected: "technical"
  },
  {
    id: "F06",
    message: "Clicking the save button makes the app shut down.",
    expected: "technical"
  },
  {
    id: "F07",
    message: "Tracking says handed to the recipient, but nothing arrived.",
    expected: "delivery"
  },
  {
    id: "F08",
    message: "Can the courier redirect my parcel to another address?",
    expected: "delivery"
  },
  {
    id: "F09",
    message: "My shipment is stuck at the sorting center.",
    expected: "delivery"
  },
  {
    id: "F10",
    message: "What languages does your support team speak?",
    expected: "other"
  },
  {
    id: "F11",
    message: "Are you hiring part-time employees?",
    expected: "other"
  },
  {
    id: "F12",
    message: "Can I visit your showroom without an appointment?",
    expected: "other"
  }
];

return cases.map(test => ({ json: test }));

const tests = $("Evaluation Dataset")
  .all()
  .map(item => item.json);

const responses = $input.all()
  .map(item => item.json);

if (tests.length !== responses.length) {
  throw new Error(
    `Expected ${tests.length} responses, got ${responses.length}`
  );
}

// This lab assumes HTTP Request preserves input item order.
// Verify IDs/order if you later introduce batching or branching.
const allowed = [
  "billing", "technical", "delivery", "other"
];

const results = [];
const perCategory = {};

for (const category of allowed) {
  perCategory[category] = {
    total: 0,
    correct: 0
  };
}

for (let i = 0; i < tests.length; i++) {
  const test = tests[i];
  const response = responses[i];

  let prediction = null;
  let error = null;

  try {
    if (response.done !== true) {
      throw new Error("Incomplete response");
    }

    const parsed = JSON.parse(response.response);

    if (
      !parsed ||
      typeof parsed !== "object" ||
      Array.isArray(parsed) ||
      typeof parsed.category !== "string"
    ) {
      throw new Error("Invalid response structure");
    }

    const category = parsed.category.trim().toLowerCase();

    if (!allowed.includes(category)) {
      throw new Error("Unsupported category");
    }

    prediction = category;
  } catch (err) {
    error = err.message;
  }

  const correct = prediction === test.expected;

  perCategory[test.expected].total++;

  if (correct) {
    perCategory[test.expected].correct++;
  }

  results.push({
    id: test.id,
    expected: test.expected,
    predicted: prediction,
    correct,
    error
  });
}

const total = results.length;
const correct = results.filter(r => r.correct).length;

return [{
  json: {
    model: "gemma3:4b",
    total,
    correct,
    incorrect: total - correct,
    accuracy_percent: Number(
      (100 * correct / total).toFixed(2)
    ),
    per_category: perCategory,
    results
  }
}];
